/** 참여자 전용 두루마리 조회 API입니다. */
package com.dandimate.durooduroo.scroll.controller;
import com.dandimate.durooduroo.common.api.ApiResponse; import com.dandimate.durooduroo.common.exception.BusinessException; import com.dandimate.durooduroo.member.repository.MemberRepository; import com.dandimate.durooduroo.scroll.repository.ScrollRepository; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/rooms/{roomId}/scroll") public class ScrollController { private final ScrollRepository scrolls; private final MemberRepository members; public ScrollController(ScrollRepository s,MemberRepository m){scrolls=s;members=m;} @GetMapping public ApiResponse<?> get(@PathVariable String roomId,@RequestHeader(required=false) String authorization){String token=com.dandimate.durooduroo.common.auth.MemberTokenResolver.resolve(authorization);members.findByRoomIdAndMemberToken(roomId,token).orElseThrow(()->new BusinessException("MEMBER_FORBIDDEN","방 참여자만 조회할 수 있습니다."));return ApiResponse.success(scrolls.findTopByRoomIdOrderByCreatedAtDesc(roomId).orElseThrow(()->new BusinessException("SCROLL_NOT_FOUND","아직 생성된 두루마리가 없습니다.")));} }
